**Minha resposta:**

Para resolver o problema de contar folhas em uma árvore binária de pesquisa, implementarei um programa simples em Java que lê os números da entrada, constrói a árvore e conta as folhas. Uma folha é um nó sem filhos (esquerdo e direito nulos). O programa será conciso e focado no problema, sem funcionalidades extras.

```java
import java.util.Scanner;

class Node {
    int value;
    Node left, right;
    Node(int value) {
        this.value = value;
        left = right = null;
    }
}

class BST {
    Node root;

    void insert(int value) {
        root = insertRec(root, value);
    }

    private Node insertRec(Node node, int value) {
        if (node == null) {
            return new Node(value);
        }
        if (value < node.value) {
            node.left = insertRec(node.left, value);
        } else if (value > node.value) {
            node.right = insertRec(node.right, value);
        }
        return node;
    }

    int countLeaves() {
        return countLeavesRec(root);
    }

    private int countLeavesRec(Node node) {
        if (node == null) {
            return 0;
        }
        if (node.left == null && node.right == null) {
            return 1;
        }
        return countLeavesRec(node.left) + countLeavesRec(node.right);
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] input = sc.nextLine().split(" ");
        BST tree = new BST();
        for (String s : input) {
            tree.insert(Integer.parseInt(s));
        }
        System.out.println(tree.countLeaves());
        sc.close();
    }
}
```

