        // Segundo dígito: dígito na posição nthDig+1 (à esquerda do primeiro)
        int digit2 = (number / (int)Math.pow(10, nthDig)) % 10;

        // Combina os dois dígitos em um número (digit2 seguido de digit1)
        return digit2 * 10 + digit1;
    }

    public static int[] countingSort(int[] arr, int nthDig) {
