public class MergeSortStepByStep {

    public static void mergeSort(int[] arr, int left, int right) {
        if (left < right) {
            int mid = (left + right) / 2;

            // Imprime subarray esquerdo antes de ordenar
            printSubArray(arr, left, mid);

            mergeSort(arr, left, mid);

            // Imprime subarray direito antes de ordenar
            printSubArray(arr, mid + 1, right);

            mergeSort(arr, mid + 1, right);

            merge(arr, left, mid, right);

            // Imprime resultado do merge
            printSubArray(arr, left, right);
        }
    }

    private static void merge(int[] arr, int left, int mid, int right) {
        int[] temp = new int[right - left + 1];
        int i = left, j = mid + 1, k = 0;

        while (i <= mid && j <= right) {
            if (arr[i] <= arr[j]) {
                temp[k++] = arr[i++];
            } else {
                temp[k++] = arr[j++];
            }
        }

        while (i <= mid) {
            temp[k++] = arr[i++];
        }

        while (j <= right) {
            temp[k++] = arr[j++];
        }

        // Copia de volta para o array original
        for (i = left, k = 0; i <= right; i++, k++) {
            arr[i] = temp[k];
        }
    }

    private static void printSubArray(int[] arr, int left, int right) {
