                if (this.table[pos].key == key) {
                    this.table[pos] = new Pair(null, null);
                    return;
                }

            }

        }

    }

    String keys() {
        ArrayList keys = new ArrayList();

        for (int i = 0; i < table.length; i++) {
            if (table[i] != null && table[i].key != null)
                keys.add(table[i].key);
        }

